#!/bin/bash
# Claude Code Custom Status Line
# Generated by claude-statusline (npx claude-statusline)
# Layout: DIR | BRANCH | CONTEXT | MODEL | COST | BLOCK_TIMER

input=$(cat)

# ============================================================
# CONFIGURATION
# ============================================================
JIRA_BASE_URL="__JIRA_BASE_URL__"
JIRA_TICKET_PREFIX="__JIRA_TICKET_PREFIX__"
BLOCK_ANCHOR_OFFSET=__BLOCK_ANCHOR_OFFSET__
BLOCK_SECONDS=18000
BLOCK_SHOW_THRESHOLD=60
BAR_WIDTH=__BAR_WIDTH__

# ============================================================
# COLORS
# ============================================================
C_RESET="\033[0m"
C_DIM="\033[0;90m"
C_MODEL="\033[0;90m"
C_DIR="__C_DIR__"
C_BRANCH="__C_BRANCH__"
C_COST="\033[0;90m"
C_DIRTY="\033[38;5;214m"
C_BAR_OK="__C_BAR_OK__"
C_BAR_WARN="__C_BAR_WARN__"
C_BAR_CRIT="__C_BAR_CRIT__"

# ============================================================
# SCRIPT
# ============================================================
model=$(echo "$input" | jq -r '.model.display_name // "Unknown"')
cwd=$(echo "$input" | jq -r '.workspace.current_dir // ""')
used_pct=$(echo "$input" | jq -r '.context_window.used_percentage // empty')
cost=$(echo "$input" | jq -r '.cost.total_cost_usd // empty')

# --- Directory ---
dir_name=""
[ -n "$cwd" ] && dir_name=$(basename "$cwd")

# --- Git Branch + Dirty ---
branch=""
dirty=""
if [ -n "$cwd" ] && git -C "$cwd" rev-parse --git-dir >/dev/null 2>&1; then
  branch=$(git -C "$cwd" --no-optional-locks rev-parse --abbrev-ref HEAD 2>/dev/null)
  if ! git -C "$cwd" --no-optional-locks diff --quiet 2>/dev/null || \
     ! git -C "$cwd" --no-optional-locks diff --cached --quiet 2>/dev/null; then
    dirty=" ${C_DIRTY}●${C_RESET}"
  fi
fi

# --- Context Progress Bar ---
ctx_str=""
if [ -n "$used_pct" ]; then
  used_int=${used_pct%.*}
  if [ "$used_int" -ge 80 ]; then
    bar_color="$C_BAR_CRIT"
  elif [ "$used_int" -ge 50 ]; then
    bar_color="$C_BAR_WARN"
  else
    bar_color="$C_BAR_OK"
  fi
  filled=$(( used_int * BAR_WIDTH / 100 ))
  empty=$(( BAR_WIDTH - filled ))
  bar=""
  for (( i=0; i<filled; i++ )); do bar="${bar}█"; done
  for (( i=0; i<empty; i++ )); do bar="${bar}░"; done
  ctx_str=$(printf "${bar_color}[%s] %d%%${C_RESET}" "$bar" "$used_int")
fi

# --- Cost ---
usage_str=""
if [ -n "$cost" ] && [ "$cost" != "null" ]; then
  cost_fmt=$(awk "BEGIN {printf \"%.2f\", $cost}")
  usage_str=$(printf "${C_COST}\$%s${C_RESET}" "$cost_fmt")
fi

# --- Block Timer ---
block_str=""
now=$(date +%s)
elapsed=$(( (now - BLOCK_ANCHOR_OFFSET) % BLOCK_SECONDS ))
remaining=$(( BLOCK_SECONDS - elapsed ))
rem_mins_total=$(( remaining / 60 ))
if [ "$rem_mins_total" -le "$BLOCK_SHOW_THRESHOLD" ]; then
  if [ "$rem_mins_total" -le 15 ]; then
    block_color="\033[38;5;203m"
    icon="⏳"
  elif [ "$rem_mins_total" -le 30 ]; then
    block_color="\033[38;5;179m"
    icon="⏳"
  else
    block_color="\033[38;5;242m"
    icon="⏱"
  fi
  block_str=$(printf "${block_color}%s %dm${C_RESET}" "$icon" "$rem_mins_total")
fi

# --- Build output ---
sep="${C_DIM} | ${C_RESET}"
parts="${C_DIR}${dir_name}${C_RESET}"

if [ -n "$branch" ]; then
  if [ -n "$JIRA_BASE_URL" ] && [[ "$branch" =~ ^${JIRA_TICKET_PREFIX}-[0-9]+ ]]; then
    jira_id="${BASH_REMATCH[0]}"
    jira_link=$(printf "\033]8;;%s/%s\007${C_BRANCH}%s${C_RESET}\033]8;;\007" "$JIRA_BASE_URL" "$jira_id" "$branch")
    parts="${parts}${sep}${jira_link}${dirty}"
  else
    parts="${parts}${sep}${C_BRANCH}${branch}${C_RESET}${dirty}"
  fi
fi

[ -n "$ctx_str" ] && parts="${parts}${sep}${ctx_str}"
parts="${parts}${sep}${C_MODEL}${model}${C_RESET}"
[ -n "$usage_str" ] && parts="${parts}${sep}${usage_str}"
[ -n "$block_str" ] && parts="${parts}${sep}${block_str}"

printf "%b\n" "$parts"
